import SwiftUIstruct TasksView: View {        @EnvironmentObject var session: UserSession    @EnvironmentObject var viewModel: DesignTokensViewModel        @State private var user: UserData? = nil    @State private var allTasks: [TaskItem] = []    // 👉 Agrupado fuera del body = NO crashea el compilador    var groupedTasks: [(subject: String, tasks: [TaskItem])] {        let dict = Dictionary(grouping: allTasks, by: { $0.subjectName })        return dict.keys.sorted().map { key in            (subject: key, tasks: dict[key] ?? [])        }    }    var body: some View {        ZStack {            Color(hex: viewModel.config?.colors.background ?? "#1C1C1E")                .ignoresSafeArea()            ScrollView {                VStack(spacing: 20) {                    header                    ForEach(groupedTasks, id: \.subject) { group in                        subjectSection(group)                    }                }                .padding(.bottom)            }        }        .onAppear(perform: loadUser)    }    private var header: some View {        Text("Tareas")            .font(.largeTitle.bold())            .foregroundColor(Color(hex: viewModel.config?.colors.mainFontColor ?? "#FFFFFF"))            .frame(maxWidth: .infinity, alignment: .leading)            .padding(.horizontal)            .padding(.top)    }    private func subjectSection(_ group: (subject: String, tasks: [TaskItem])) -> some View {        VStack(alignment: .leading, spacing: 16) {            Text(group.subject)                .font(.title2.bold())                .foregroundColor(Color(hex: viewModel.config?.colors.mainFontColor ?? "#FFFFFF"))                .padding(.horizontal)            VStack(spacing: 28) {                ForEach(group.tasks) { task in                    TimelineTaskRow(                        task: task,                        toggle: { toggleTask(task) }                    )                    .environmentObject(viewModel)                    .environmentObject(session)                }            }            .padding(.leading, 28)        }    }    private func loadUser() {        guard            let email = session.currentUser?.email,            let foundUser = viewModel.config?.userData.first(where: { $0.email == email })        else { return }        self.user = foundUser        self.allTasks = foundUser.subjects.flatMap { $0.tasks }    }    private func toggleTask(_ task: TaskItem) {        guard let index = allTasks.firstIndex(where: { $0.id == task.id }) else { return }        withAnimation(.spring()) {            allTasks[index].isCompleted.toggle()        }    }}